template<class Iterator> struct iterator_traits {
    typedef typename Iterator::difference_type difference_type;  // Implementation note: This uses dependent name lookup; if Iterator doesn't have this, it's a compile-time error.
    typedef typename Iterator::value_type value_type;           // The compiler defers resolution until the template is instantiated.
    typedef typename Iterator::pointer pointer;
    typedef typename Iterator::reference reference;
    typedef typename Iterator::iterator_category iterator_category;
};

template<class T> struct iterator_traits<T*> {  // Partial specialization for pointers
    typedef ptrdiff_t difference_type;            // Implementation note: Directly defined, bypassing nested types in pointers.
    typedef T value_type;
    typedef T* pointer;
    typedef T& reference;
    typedef random_access_iterator_tag iterator_category;  // The compiler selects this specialization when Iterator is a pointer type.
};

code_example:
#include <iostream>
#include <iterator>
#include <vector>

int main() {
    std::vector<int> vec{1, 2, 3};
    typedef std::vector<int>::iterator VecIter;  // A custom iterator type

    // Using std::iterator_traits
    typedef std::iterator_traits<VecIter>::value_type ValueType;  // Compile-time resolution
    typedef std::iterator_traits<int*>::value_type PointerValueType;  // Specialization for pointers

    ValueType val = 10;  // Should be int, based on VecIter's traits
    std::cout << "Value type of vector iterator: " << val << std::endl;  // Output: 10

    int arr[3] = {4, 5, 6};
    int* ptr = arr;
    PointerValueType ptrVal = *ptr;  // Should be int, from pointer specialization
    std::cout << "Value via pointer: " << ptrVal << std::endl;  // Output: 4
    return 0;
}
